<?php
require_once __DIR__ . '/auth.php';
require_once __DIR__ . '/asaas.php';
require_once __DIR__ . '/mailer.php';
require_once __DIR__ . '/anti_bot.php';

if (usuarioLogado()) { header('Location: admin.php'); exit; }

$planos    = db()->query("SELECT * FROM planos WHERE ativo=1 ORDER BY ordem")->fetchAll();
$plano_pre = (int)($_GET['plano'] ?? 2);

$erro   = '';
$sucesso = '';

// ── Validação de senha forte ───────────────────────────────
function senha_forte(string $senha): ?string {
    if (strlen($senha) < 8)                          return 'A senha deve ter no mínimo 8 caracteres.';
    if (!preg_match('/[A-Z]/', $senha))              return 'A senha deve conter ao menos uma letra maiúscula.';
    if (!preg_match('/[0-9]/', $senha))              return 'A senha deve conter ao menos um número.';
    if (!preg_match('/[^a-zA-Z0-9]/', $senha))       return 'A senha deve conter ao menos um caractere especial (!@#$%...).';
    return null;
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $plano_id  = (int)($_POST['plano_id']     ?? 1);
    $nome_emp  = trim($_POST['nome_empresa']  ?? '');
    $nome_resp = trim($_POST['nome']          ?? '');
    $email     = strtolower(trim($_POST['email'] ?? ''));
    $telefone  = trim($_POST['telefone']      ?? '');
    $documento = trim($_POST['documento']     ?? '');
    $senha     = $_POST['senha']              ?? '';
    $senha2    = $_POST['senha2']             ?? '';

    // Validações
    if (!$nome_emp || !$nome_resp || !$email || !$senha) {
        $erro = 'Todos os campos obrigatórios devem ser preenchidos.';
    } elseif (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        $erro = 'E-mail inválido.';
    } elseif ($erro_senha = senha_forte($senha)) {
        $erro = $erro_senha;
    } elseif ($senha !== $senha2) {
        $erro = 'As senhas não conferem.';
    } else {
        $ck = db()->prepare("SELECT id FROM usuarios WHERE email=?");
        $ck->execute([$email]);
        if ($ck->fetch()) $erro = 'Este e-mail já está cadastrado.';
    }

    // Anti-bot (honeypot, tempo, limite por IP, domínio, Gmail com pontos, hCaptcha)
    if (!$erro) $erro = ab_checar($_POST) ?? '';

    if (!$erro) {
        // Gera slug único
        $slug_base = preg_replace('/[^a-z0-9]+/', '-', strtolower($nome_emp));
        $slug = $slug_base; $n = 1;
        while (true) {
            $ck = db()->prepare("SELECT id FROM tenants WHERE slug=?");
            $ck->execute([$slug]);
            if (!$ck->fetch()) break;
            $slug = $slug_base . '-' . (++$n);
        }

        $plano = db()->prepare("SELECT * FROM planos WHERE id=?");
        $plano->execute([$plano_id]);
        $plano = $plano->fetch();
        if (!$plano) $plano_id = 1;

        // Token de confirmação (64 hex chars, expira em 24h)
        $token       = bin2hex(random_bytes(32));
        $token_expira = date('Y-m-d H:i:s', strtotime('+24 hours'));

        db()->beginTransaction();
        try {
            $trial_end = date('Y-m-d', strtotime('+' . TRIAL_DAYS . ' days'));

            db()->prepare("INSERT INTO tenants (nome_empresa,slug,email_admin,telefone,documento,plano_id,status,trial_ends_at)
                           VALUES (?,?,?,?,?,?,'trial',?)")
                ->execute([$nome_emp,$slug,$email,$telefone,$documento,$plano_id,$trial_end]);
            $tenant_id = (int)db()->lastInsertId();

            $hash = password_hash($senha, PASSWORD_BCRYPT);
            db()->prepare("INSERT INTO usuarios (tenant_id,nome,email,senha_hash,tipo,email_verificado,email_token,email_token_expira)
                           VALUES (?,?,?,?,'admin',0,?,?)")
                ->execute([$tenant_id,$nome_resp,$email,$hash,$token,$token_expira]);

            db()->commit();

            // Asaas (best-effort)
            $payment_url = '';
            try {
                $customer_id = asaas_criar_cliente(['nome'=>$nome_resp,'email'=>$email,'telefone'=>$telefone,'documento'=>$documento]);
                if ($customer_id) {
                    $assinatura = asaas_criar_assinatura($customer_id, $plano['preco_centavos'], 'Opa Studio — Plano ' . $plano['nome']);
                    db()->prepare("UPDATE tenants SET asaas_customer_id=?, asaas_subscription_id=? WHERE id=?")
                        ->execute([$customer_id, $assinatura['subscription_id'] ?? null, $tenant_id]);
                    $payment_url = $assinatura['payment_url'] ?? '';
                }
            } catch (Exception $e) {}

            // Envia e-mail de confirmação
            mailer_confirmacao($email, $nome_resp, $token);

            // Redireciona para página de sucesso (aguardando confirmação)
            $dest = $payment_url ? 'obrigado.php?pay=' . urlencode($payment_url) . '&confirmar=1' : 'obrigado.php?confirmar=1';
            header('Location: ' . $dest);
            exit;

        } catch (Exception $e) {
            db()->rollBack();
            $erro = 'Erro ao criar conta. Tente novamente.';
        }
    }
}
