<script>
// ── TOGGLE SENHA ────────────────────────────────────────────
const EYE_OPEN = `<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>`;
const EYE_SHUT = `<path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19m-6.72-1.07a3 3 0 11-4.24-4.24"/>
<line x1="1" y1="1" x2="23" y2="23"/>`;

function togglePass(inputId, iconId) {
  const inp = document.getElementById(inputId);
  const ico = document.getElementById(iconId);
  const isPass = inp.type === 'password';
  inp.type = isPass ? 'text' : 'password';
  ico.innerHTML = isPass ? EYE_SHUT : EYE_OPEN;
}

// ── VALIDAÇÃO DE SENHA FORTE ────────────────────────────────
function avaliarSenha(v) {
  const reqs = {
    'r-len':   v.length >= 8,
    'r-upper': /[A-Z]/.test(v),
    'r-num':   /[0-9]/.test(v),
    'r-spec':  /[^a-zA-Z0-9]/.test(v),
  };
  let pts = Object.values(reqs).filter(Boolean).length;

  Object.entries(reqs).forEach(([id, ok]) => {
    document.getElementById(id).classList.toggle('ok', ok);
  });

  const cores = ['','#f87171','#fbbf24','#78be20','#4ade80'];
  const labels = ['','Fraca','Média','Boa','Forte'];
  [1,2,3,4].forEach(i => {
    const seg = document.getElementById('s'+i);
    seg.style.background = i <= pts ? cores[pts] : 'var(--border)';
  });

  const lbl = document.getElementById('strengthLabel');
  lbl.textContent = v.length ? labels[pts] : '';
  lbl.style.color = cores[pts] || 'var(--muted)';

  checarConfirmacao();
  atualizarBotao(pts, reqs);
}

function checarConfirmacao() {
  const s1 = document.getElementById('senhaInput').value;
  const s2 = document.getElementById('senha2Input').value;
  const lbl = document.getElementById('matchLabel');
  if (!s2) { lbl.textContent = ''; return; }
  if (s1 === s2) { lbl.textContent = '✓ Senhas coincidem'; lbl.style.color = 'var(--success)'; }
  else           { lbl.textContent = '✗ Senhas não coincidem'; lbl.style.color = 'var(--danger)'; }
}

function atualizarBotao(pts, reqs) {
  const btn = document.getElementById('btnSubmit');
  const tudo = Object.values(reqs).every(Boolean);
  btn.disabled = !tudo;
  btn.title    = tudo ? '' : 'Complete os requisitos de senha';
}

// ── PLANO ───────────────────────────────────────────────────
function selecionarPlano(id) {
  document.getElementById('planoId').value = id;
  document.querySelectorAll('.plan-opt').forEach(el =>
    el.classList.toggle('active', parseInt(el.dataset.id) === id)
  );
}

// ── SUBMIT: feedback visual ─────────────────────────────────
document.getElementById('formReg').addEventListener('submit', function(e) {
  const btn = document.getElementById('btnSubmit');
  btn.textContent = 'Criando conta...';
  btn.disabled = true;
});
</script>
<script>
(function(){
  const DARK  = "data:image/png;base64,";
  const LIGHT = "data:image/png;base64,";
  function syncLogos(){
    const isLight = window.matchMedia('(prefers-color-scheme:light)').matches;
    const src = isLight ? LIGHT : DARK;
    ['navLogo','logoMain','logoReg','heroLogo','logoFb'].forEach(id=>{
      const el = document.getElementById(id);
      if(el && el.tagName==='IMG') el.src = src;
    });
  }
  window.matchMedia('(prefers-color-scheme:light)').addEventListener('change', syncLogos);
  document.addEventListener('DOMContentLoaded', syncLogos);
  syncLogos();
})();
</script>
